export const faqCategories: Record<FaqCategory, string> = {
  PUBLIC_ELECTION: '공직선거법',
  PARTY_FUND: '정당/정치자금',
  CAMPAIGN: '선거운동',
  DONATION: '기부행위',
  SNS: '온라인/SNS',
  VOTING: '투표',
  OTHER: '기타',
};

/**
 * 한국어 조사 제거
 */
function removeKoreanParticles(text: string): string {
  return text
    .replace(/[은는이가을를의로에서와과도만까지부터처럼같이]/g, ' ')
    .replace(/인가요|인지|할까요|하나요|뭔가요|있나요|되나요|할수/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * 키워드 기반 FAQ 검색 (점수 기반 랭킹)
 */
export function searchFaq(query: string): ElectionLawFaqItem[] {
  const cleanQuery = removeKoreanParticles(query.toLowerCase());
  const keywords = cleanQuery.split(' ').filter((k) => k.length >= 2);
  if (keywords.length === 0) return [];

  const scored = electionLawFaq.map((item) => {
    const questionLower = item.question.toLowerCase();
    const answerLower = item.answer.toLowerCase();
    let score = 0;
    for (const kw of keywords) {
      if (questionLower.includes(kw)) score += 3;
      if (answerLower.includes(kw)) score += 1;
      if (item.keywords.some((k) => k.toLowerCase().includes(kw))) score += 2;
      if (item.categoryLabel.includes(kw)) score += 2;
    }
    return { item, score };
  });

  return scored
    .filter((s) => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .map((s) => s.item);
}

/**
 * 카테고리별 FAQ 필터
 */
export function filterByCategory(category: FaqCategory): ElectionLawFaqItem[] {
  return electionLawFaq.filter((item) => item.category === category);
}
